const canvas=document.querySelector('#game');canvas.width=canvas.height=900;const ctx=canvas.getContext('2d'),colors=['#43edb1','#ffbb32','#34cfff','#ff386a'];function world(i,u,d){return i===0?[u,800-d]:i===1?[u,100+d]:i===2?[100+d,u]:[800-d,u];}
function line(x1,y1,x2,y2,color,w=1){ctx.strokeStyle=color;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();}
function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}}
function draw({players,balls,particles,shake}){ctx.clearRect(0,0,900,900);ctx.save();if(shake)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);ctx.fillStyle='#0d1719';ctx.fillRect(0,0,900,900);for(let x=0;x<900;x+=40)for(let y=0;y<900;y+=40){ctx.fillStyle='#263331';ctx.fillRect(x,y,2,2);}roundRect(80,80,740,740,36,'#1b2a29','#3d5048');roundRect(100,100,700,700,20,'#142220');ctx.save();ctx.beginPath();ctx.rect(100,100,700,700);ctx.clip();for(let x=100;x<=800;x+=50){line(x,100,x,800,'#23352f');line(100,x,800,x,'#23352f');}ctx.strokeStyle='#33473c';ctx.lineWidth=2;ctx.beginPath();ctx.arc(450,450,120,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(450,450,42,0,Math.PI*2);ctx.stroke();line(100,450,800,450,'#30443b');line(450,100,450,800,'#30443b');ctx.restore();ctx.save();ctx.translate(450,450);ctx.rotate(-Math.PI/4);roundRect(-23,-23,46,46,5,'#233a31','#476047');ctx.restore();ctx.fillStyle='#749275';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.fillText('B',450,455);
for(let i=0;i<4;i++){const p=players[i];ctx.save();if(i===0){ctx.translate(0,900);ctx.scale(1,-1);}else if(i===2){ctx.transform(0,1,1,0,0,0);}else if(i===3){ctx.transform(0,1,-1,0,900,0);}const col=p.hp?colors[i]:'#64716c';ctx.globalAlpha=p.hp?.85:.5;roundRect(209,83,482,18,4,'#142321',col);for(let x=220;x<690;x+=18)line(x,84,x-8,98,col,2);ctx.globalAlpha=1;line(210,103,690,103,col,3);roundRect(94,92,115,22,6,'#4a5b4c','#6c7b62');roundRect(691,92,115,22,6,'#4a5b4c','#6c7b62');for(const x of [112,190,710,788]){ctx.fillStyle='#1c2b24';ctx.beginPath();ctx.arc(x,103,4,0,Math.PI*2);ctx.fill();}if(!p.hp){roundRect(210,97,480,17,3,'#52655a');ctx.restore();continue;}line(260,132,640,132,'#42544c',2);ctx.shadowColor=col;ctx.shadowBlur=16;roundRect(p.p-55,116,110,21,7,col);ctx.shadowBlur=0;roundRect(p.p-37,123,74,35,9,'#263b35',col);roundRect(p.p-20,130,40,17,4,'#1b2525');line(p.p-13,136,p.p+13,136,col,3);for(const x of [p.p-47,p.p+47])roundRect(x-8,121,16,22,4,'#111c1b','#53665b');if(p.pulse>0){ctx.globalAlpha=p.pulse/.22;ctx.strokeStyle=col;ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(p.p,130,76,60,0,0,Math.PI);ctx.stroke();}ctx.restore();}
ctx.textAlign='center';ctx.font='600 11px sans-serif';for(const p of players){const [x,y]=world(p.i,450,-44);ctx.save();ctx.translate(x,y);if(p.i===2)ctx.rotate(-Math.PI/2);if(p.i===3)ctx.rotate(Math.PI/2);ctx.fillStyle=colors[p.i];ctx.globalAlpha=p.hp?1:.3;ctx.fillText(p.i===0?'MOR / YOU':p.name+' / CPU',0,0);ctx.restore();}
for(const b of balls){const c=b.owner>=0?colors[b.owner]:'#f1e8c7';ctx.globalAlpha=1;ctx.shadowColor=c;ctx.shadowBlur=0;const metal=ctx.createLinearGradient(b.x-b.r,b.y-b.r,b.x+b.r,b.y+b.r);metal.addColorStop(0,'#edf5ff');metal.addColorStop(.22,c);metal.addColorStop(.46,'#172331');metal.addColorStop(.58,'#ffffff');metal.addColorStop(.72,c);metal.addColorStop(1,'#15202c');ctx.fillStyle=metal;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fffce8';ctx.beginPath();ctx.arc(b.x-2,b.y-3,3,0,Math.PI*2);ctx.fill();}for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,4,4);}ctx.globalAlpha=1;ctx.restore();}

window.arena3D={render:draw,pointer(e){const r=canvas.getBoundingClientRect();return (e.clientX-r.left)/r.width*900;},setQuality(){}};document.body.classList.add('compatibility');document.querySelector('.header-status').textContent='COMPATIBILITY VIEW · WEBGL UNAVAILABLE';document.querySelector('#quality').hidden=true;await import('./game.js');document.querySelector('#loading').hidden=true;